from playwright.sync_api import sync_playwright
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch()
    for name,vw in (('phone390',390),('phone320',320),('desktop',1100)):
        ctx=b.new_context(service_workers='block',viewport={'width':vw,'height':844}); pg=ctx.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
        pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file','/home/claude/Transactions.csv'); pg.wait_for_selector('#setup',timeout=20000)
        ok(name+': version 16.2', pg.evaluate("(async()=>(await import('/js/version.js')).versionText())()").startswith('16.2'))
        # review
        pg.goto('http://localhost:8123/#/ledger'); pg.wait_for_timeout(900); pg.click('.reviewbtn'); pg.wait_for_timeout(600)
        h=pg.evaluate("(()=>{const bb=document.querySelector('[data-act=review-back]').getBoundingClientRect(),t=document.querySelector('header.top h1').getBoundingClientRect();return {b:[bb.right,bb.top,bb.bottom],t:[t.left,t.top,t.bottom],txt:document.querySelector('header.top h1').textContent}})()")
        ok(name+': back arrow just left of Review title, aligned %s'%h, h['txt']=='Review' and 0<=h['t'][0]-h['b'][0]<12 and abs((h['b'][1]+h['b'][2])/2-(h['t'][1]+h['t'][2])/2)<3)
        pg.click('[data-act=review-back]'); pg.wait_for_timeout(500)
        ok(name+': back goes to the previous tab', pg.evaluate("location.hash")=='#/ledger')
        pg.click('.burger'); pg.wait_for_timeout(500)
        ok(name+': menu has no Review item', pg.evaluate("![...document.querySelectorAll('.drawer a, .drawer button, [role=dialog] a')].some(e=>e.textContent.trim().startsWith('Review'))"))
        pg.keyboard.press('Escape')
        # calendar
        pg.goto('http://localhost:8123/#/calendar'); pg.wait_for_timeout(900)
        c=pg.evaluate("(()=>{const q=s=>document.querySelector(s),card=q('.calsum'),items=[...card.children].map(e=>e.querySelector('span').textContent),lg=q('.legend.cal-l'),cal=q('.cal'),r=e=>e.getBoundingClientRect();return {items,facts:document.querySelectorAll('.facts.three').length,lg:lg.textContent.replace(/\\s+/g,' '),order:r(card).bottom<=r(lg).top&&r(lg).bottom<=r(cal).top,radius:getComputedStyle(card).borderRadius,sh:getComputedStyle(card).boxShadow!=='none',over:document.documentElement.scrollWidth>innerWidth}})()")
        print(c)
        ok(name+': 4 items, Transfer right after Net Income', c['items']==['Cash Inflow','Cash Outflow','Net Income','Transfer'])
        ok(name+': second card gone', c['facts']==0)
        ok(name+': legend under card with new labels', c['lg'].strip()=='Cash Outflow (darker = more) Cash Inflow Transfer' and c['order'])
        ok(name+': shared card design, no overflow', c['radius']=='24px' and c['sh'] and not c['over'])
        # home
        pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1500)
        s=pg.evaluate("(()=>{const e=document.querySelector('.spcard');if(!e)return null;return {n:document.querySelectorAll('.spendable,.safeto').length,txt:e.innerText.replace(/\\s+/g,' '),two:e.classList.contains('two'),r:getComputedStyle(e).borderRadius,over:e.scrollWidth>e.clientWidth+1}})()")
        print(s)
        ok(name+': Spendable card present (one card, new design)', s and s['n']==0 and s['r']=='24px' and not s['over'])
        if s and s['two']: ok(name+': both values and notes', 'Spendable Now' in s['txt'] and 'Safe to Spend' in s['txt'] and 'already owed' in s['txt'] and 'before anything you owe' in s['txt'])
        ok(name+': no errors %s'%errs, not errs)
        ctx.close()
    ctx=b.new_context(service_workers='block',viewport={'width':390,'height':844}); pg=ctx.new_page()
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file','/home/claude/Transactions.csv'); pg.wait_for_selector('#setup',timeout=20000)
    pg.evaluate("localStorage.setItem('sukli-look', JSON.stringify({design:'legacy'}))"); pg.reload(); pg.wait_for_timeout(1200)
    pg.goto('http://localhost:8123/#/calendar'); pg.wait_for_timeout(900)
    ok('legacy calendar unchanged', pg.evaluate("document.querySelectorAll('.facts.three').length===1&&!document.querySelector('.calsum')&&document.querySelectorAll('.strip').length===1"))
    pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1200)
    ok('legacy spendable unchanged', pg.evaluate("!document.querySelector('.spcard')&&!!document.querySelector('.spendable')"))
    pg.click('.burger'); pg.wait_for_timeout(500)
    ok('legacy menu keeps Review', pg.evaluate("[...document.querySelectorAll('a')].some(e=>e.textContent.trim().startsWith('Review'))"))
